// Tells a Claude Code session inside lich when another lich session edited the
// file it is editing. Docs: ../docs/edit-guard.md. No lich contract behind it:
// the sessions meet in the checkout's git dir, not over HTTP.
//
// A subagent lich opens shares its caller's checkout, so two sessions can edit
// one file. Claude Code already refuses an edit that would overwrite a change
// it has not read (measured on 2.1.289, in the doc), so this is coordination,
// not protection: every edit leaves a marker naming the session, and an edit
// to a file another session marked recently carries a note naming it.
//
// Every function that takes `$` is declared here at the top level: the loader
// refuses a module that hands `$` to a nested function.

import { promptLang, say } from "./prompt-text.js"
import { setStatusPart } from "./status-line.js"

// Long enough to span the other session's turn that made the edit, short
// enough that a marker from work long finished stops raising notes.
const RECENT_MS = 10 * 60_000
const MARKER_DIR = "lich-edits"
const GIT_TIMEOUT_MS = 5_000
// The edit's result waits on it, so it is cut well short of the git timeout.
const LICH_TIMEOUT_MS = 2_000

/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {{ path: string, session: string, at: number }} Marker
 * @typedef {{ label: string, id?: string }} Peer
 */

/** FNV-1a, 32 bits: a file name for a path; the marker keeps the path itself. */
function hashOf(text) {
  let hash = 0x811c9dc5
  for (let i = 0; i < text.length; i++) {
    hash ^= text.charCodeAt(i)
    hash = Math.imul(hash, 0x01000193)
  }
  return (hash >>> 0).toString(16).padStart(8, "0")
}

/** @param {string} path */
function folderOf(path) {
  const cut = Math.max(path.lastIndexOf("/"), path.lastIndexOf("\\"))
  return cut <= 0 ? path.slice(0, cut + 1) || "." : path.slice(0, cut)
}

/**
 * Where the marker for `path` lives, or undefined outside a git repository.
 *
 * @param {Engine} $
 * @param {string} path
 */
async function markerPathOf($, path) {
  const git = await $.process.run(["git", "-C", folderOf(path), "rev-parse", "--absolute-git-dir"], {
    timeoutMs: GIT_TIMEOUT_MS,
  })
  if (git.exitCode !== 0) return undefined
  return `${git.stdout.trim()}/${MARKER_DIR}/${hashOf(path)}`
}

/**
 * The marker another session left on `path`, if any.
 *
 * @param {Engine} $
 * @param {string} markerPath
 * @param {string} path
 * @returns {Promise<Marker | undefined>}
 */
async function readMarker($, markerPath, path) {
  if (!(await $.fs.exists(markerPath))) return undefined
  /** @type {Marker} */
  const marker = JSON.parse(await $.fs.read(markerPath))
  return marker.path === path ? marker : undefined
}

/**
 * @param {Marker | undefined} marker
 * @param {string} session
 * @param {number} now
 * @returns {marker is Marker}
 */
function isNews(marker, session, now) {
  return !!marker && marker.session !== session && now - marker.at <= RECENT_MS
}

/**
 * The label on the card of the session `id`, or undefined when lich cannot say.
 *
 * A lich older than the `id` field in `lich sessions --json` lists none, and
 * the session goes unnamed there.
 *
 * @param {Engine} $
 * @param {string} id
 */
async function labelOf($, id) {
  const lich = await $.env.get("LICH_BIN")
  if (!lich) return undefined
  const { exitCode, stdout } = await $.process.run([lich, "sessions", "--json"], { timeoutMs: LICH_TIMEOUT_MS })
  if (exitCode !== 0) return undefined
  /** @type {Peer[]} */
  const peers = JSON.parse(stdout)
  return peers.find((peer) => peer.id === id)?.label
}

/**
 * @param {Marker} marker
 * @param {string} who
 * @param {number} now
 * @param {string} lang
 */
function noteFor(marker, who, now, lang) {
  const minutes = Math.round((now - marker.at) / 60_000)
  const ago = minutes === 0 ? say(lang, "editNoteJustNow") : say(lang, "editNoteAgo", { minutes })
  return say(lang, "editNote", { path: marker.path, who, at: new Date(marker.at).toISOString(), ago })
}

/**
 * The session that left `marker`, by label when lich can say which.
 *
 * @param {Engine} $
 * @param {Marker} marker
 */
async function whoMarked($, marker) {
  let label
  try {
    label = await labelOf($, marker.session)
  } catch (error) {
    logFailure($, error)
  }
  return label ? `"${label}"` : marker.session
}

/** The marker the status line shows, so an older one's timer does not clear a newer one. @type {Marker | undefined} */
let shownMarker

/**
 * Tells the user too, in the status line, until the marker stops being news.
 * The note only reaches the model.
 *
 * @param {Engine} $
 * @param {Marker} marker
 * @param {string} who
 */
function showEditBy($, marker, who) {
  shownMarker = marker
  const name = marker.path.slice(Math.max(marker.path.lastIndexOf("/"), marker.path.lastIndexOf("\\")) + 1)
  setStatusPart("edits", `${name} also edited by ${who}`)
  $.ui.invalidate("ui.render")
}

/**
 * @param {Engine} $
 * @param {Marker} marker
 */
function clearEditBy($, marker) {
  if (shownMarker !== marker) return
  shownMarker = undefined
  setStatusPart("edits", undefined)
  $.ui.invalidate("ui.render")
}

/** @param {Engine} $ @param {unknown} error */
function logFailure($, error) {
  $.ui.log(`lich edit guard: ${error instanceof Error ? error.message : String(error)}`)
}

/**
 * @param {Engine} $
 * @param {{ file_path?: string, notebook_path?: string }} e
 * @param {(e: any) => Promise<any>} next
 */
async function guard($, e, next) {
  const session = await $.env.get("LICH_SESSION_ID")
  const path = e.file_path ?? e.notebook_path
  if (!session || !path) return next(e)

  let markerPath
  let previous
  try {
    markerPath = await markerPathOf($, path)
    previous = markerPath && (await readMarker($, markerPath, path))
  } catch (error) {
    logFailure($, error)
    return next(e)
  }

  const result = await next(e)
  if (!markerPath || result.deny !== undefined) return result

  let note
  try {
    const now = await $.clock.now()
    if (isNews(previous, session, now)) {
      const who = await whoMarked($, previous)
      note = noteFor(previous, who, now, promptLang(await $.env.get("LICH_PROMPT_LANG")))
      showEditBy($, previous, who)
      $.clock.after(previous.at + RECENT_MS - now, () => clearEditBy($, previous))
    }
    if (!result.isError) await $.fs.write(markerPath, JSON.stringify({ path, session, at: now }))
  } catch (error) {
    logFailure($, error)
  }
  return note ? { ...result, context: [...(result.context ?? []), note] } : result
}

/** @param {import('claude-code').On} on */
export function register(on) {
  on("tool.call", { tool: "Edit" }, guard)
  on("tool.call", { tool: "Write" }, guard)
  on("tool.call", { tool: "NotebookEdit" }, guard)
}

files.hooks/mod-control.js:
// Lets lich drive a Claude Code session (`lich control`, the `control_session`
// MCP tool). Contract: ../docs/mod-control.md,
// canonical in https://github.com/omartelo/lich/blob/main/docs/hooks/mod-control.md
//
// A Claude Code mod, not a hook script: hooks/hooks.json names this file under
// `modules`, and Claude Code runs it inside its own process. It reports nothing.
// It holds a long poll open on lich, applies the commands that come back and
// acks each one. A Claude Code that does not run mods ignores the `modules`
// key, and the scripts beside this file keep reporting as before.
//
// Everything outside the module is reached through `$`, which is why every
// function that takes it is declared here at the top level: the loader refuses
// a module that hands `$` to a nested function.

import { promptLang, say } from "./prompt-text.js"

// Sent as X-Lich-Plugin on every request; bumped at release (CLAUDE.md, Release).
const PLUGIN_VERSION = "0.20.0"

const SETTLE_WHEN_IDLE = new Set(["prompt", "command"])

// The contract's client rule: after a network error or a 5xx, wait 1 second,
// doubling up to 10, and start over after a 200.
const FIRST_BACKOFF_MS = 1000
const MAX_BACKOFF_MS = 10000

// The levels `turn.step` takes. The engine checks an effort only when the next
// model request goes out, long after the command was acked `ok`, and then skips
// the hook, so a level outside these is refused here, where lich hears of it.
const EFFORTS = new Set(["low", "medium", "high", "xhigh", "max"])

// The contract cuts an answer at this many UTF-16 units, which keeps an ack
// under lich's 64 KiB body limit; a fork has no length bound of its own.
const ANSWER_LIMIT = 16000

/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {{ status: string, summary: string }} Notification
 * @typedef {'low' | 'medium' | 'high' | 'xhigh' | 'max'} Effort
 * @typedef {{ id: string, kind: string, text?: string, notification?: Notification, model?: string, effort?: string, name?: string, args?: string, question?: string }} Command
 * @typedef {{
 *   base: string,
 *   token: string,
 *   session: string,
 *   backoffMs: number,
 *   applying: Promise<void>,
 * }} Link
 * @typedef {{
 *   link?: Link,
 *   turnId?: string,
 *   model?: string,
 *   effort?: Effort,
 *   lang?: string,
 * }} State
 */

/**
 * @param {Engine} $
 * @returns {Promise<Link | undefined>}
 */
async function linkFromEnv($) {
  const [port, token, session] = await Promise.all([
    $.env.get("LICH_PORT"),
    $.env.get("LICH_TOKEN"),
    $.env.get("LICH_SESSION_ID"),
  ])
  if (!port || !token || !session) return undefined
  return { base: `http://127.0.0.1:${port}`, token, session, backoffMs: 0, applying: Promise.resolve() }
}

/**
 * One poll, then the next one scheduled: at once after a 200, later after a
 * failure, never after a 404 (a lich older than the contract).
 *
 * @param {Engine} $
 * @param {State} state
 * @param {Link} link
 */
async function poll($, state, link) {
  const url = `${link.base}/mod/commands?token=${link.token}&session_id=${link.session}`
  /** @type {Command[]} */
  let commands
  try {
    const response = await $.http.fetch(url, { headers: { "X-Lich-Plugin": PLUGIN_VERSION } })
    if (response.status === 404) return
    if (!response.ok) throw new Error(`lich answered ${response.status}`)
    commands = JSON.parse(response.text)
  } catch {
    link.backoffMs = Math.min(link.backoffMs * 2 || FIRST_BACKOFF_MS, MAX_BACKOFF_MS)
    $.clock.after(link.backoffMs, () => void poll($, state, link))
    return
  }
  link.backoffMs = 0
  for (const command of commands) {
    // An answer can take a minute and changes nothing the other commands
    // depend on, so it is not queued behind them, nor they behind it.
    if (command.kind === "ask") {
      void applyAndAck($, state, link, command)
      continue
    }
    link.applying = link.applying.then(() => {
      const acked = applyAndAck($, state, link, command)
      // A prompt or a slash command settles only once the session is idle and
      // it ran. Waiting on one would hold an abort meant for the running turn
      // until that turn ended, and a prompt's abort would then cancel the turn
      // the prompt started instead.
      if (!SETTLE_WHEN_IDLE.has(command.kind)) return acked
    })
  }
  $.clock.after(0, () => void poll($, state, link))
}

/**
 * Applies one command and acks it. Every command but a `prompt` or a `command`
 * holds the next one until its ack is answered: an `abort` ack makes lich end
 * the turn it has open, so one landing after the next `prompt` opened a turn
 * would end that turn instead.
 *
 * @param {Engine} $
 * @param {State} state
 * @param {Link} link
 * @param {Command} command
 */
async function applyAndAck($, state, link, command) {
  /** @type {{ ok: boolean, error?: string, answer?: string }} */
  let outcome
  try {
    outcome = { ok: true, ...(await apply($, state, command)) }
  } catch (error) {
    outcome = { ok: false, error: error instanceof Error ? error.message : String(error) }
  }
  try {
    await $.http.fetch(`${link.base}/mod/acks?token=${link.token}`, {
      method: "POST",
      headers: { "content-type": "application/json", "X-Lich-Plugin": PLUGIN_VERSION },
      body: JSON.stringify({ session_id: link.session, id: command.id, kind: command.kind, ...outcome }),
    })
  } catch {
    // The contract drops an ack that cannot be sent: lich never resends the command.
  }
}

/**
 * @param {Engine} $
 * @param {State} state
 * @param {Command} command
 * @returns {Promise<{ answer: string } | undefined>} what the ack carries beyond `ok`
 */
async function apply($, state, command) {
  switch (command.kind) {
    case "prompt": {
      const text = command.text ?? ""
      const submitted = await $.prompt.submit(
        command.notification ? { text: notificationText(command.notification, text), asUser: true } : { text },
      )
      if (submitted.drop !== undefined) throw new Error(submitted.drop)
      return
    }
    case "abort":
      if (state.turnId === undefined) throw new Error("no turn is running")
      await $.turn.abort({ turnId: state.turnId })
      return
    case "model":
      state.model = command.model
      return
    case "effort":
      if (command.effort !== undefined && !EFFORTS.has(command.effort)) throw new Error("unknown effort")
      state.effort = /** @type {Effort | undefined} */ (command.effort)
      return
    case "command":
      await $.command.run({ command: command.name ?? "", args: command.args })
      return
    case "ask":
      return { answer: await answer($, command.question ?? "", state.lang) }
    default:
      throw new Error("unknown kind")
  }
}

/**
 * A prompt lich marks as news from outside the session, in the shape Claude
 * Code gives its own background agent's completion: it shows `summary` as one
 * line and the model reads the whole text. `text` goes in unescaped because the
 * model reads it byte for byte, entities included; Claude Code decodes them in
 * the line it shows (measured on 2.1.289).
 *
 * @param {Notification} notification
 * @param {string} text
 */
function notificationText(notification, text) {
  return (
    `<task-notification>\n<status>${escapeXml(notification.status)}</status>\n` +
    `<summary>${escapeXml(notification.summary)}</summary>\n<result>${text}</result>\n</task-notification>`
  )
}

/** @param {string} value */
function escapeXml(value) {
  return value.replaceAll("&", "&amp;").replaceAll("<", "&lt;").replaceAll(">", "&gt;")
}

/**
 * The session's answer to a side question: a fork of its own conversation, cut
 * at ANSWER_LIMIT. A fork with no answer throws its reason, which the ack
 * carries as its error.
 *
 * @param {Engine} $
 * @param {string} question
 * @param {string} lang
 */
async function answer($, question, lang) {
  // The preamble goes before the question: without it, a fork made while a turn
  // runs reaches for a tool, is refused (a fork has none) and answers in a second
  // request, at twice the latency and the uncached tokens: measured on Claude
  // Code 2.1.289.
  const reply = await $.model.fork({ prompt: say(lang, "askPreamble") + question })
  if (!reply.isAnswered) {
    throw new Error(reply.reason === "api-error" ? `api-error ${reply.status} ${reply.error}` : reply.reason)
  }
  if (reply.text.length <= ANSWER_LIMIT) return reply.text
  return `${reply.text.slice(0, ANSWER_LIMIT)}\n[truncated]`
}

/** @param {import('claude-code').On} on */
export function register(on) {
  /** @type {State} */
  const state = {}

  on("session.start", async ($, e, next) => {
    // A `claude -p` holds its run open until a parked poll returns, up to 25
    // seconds, and one started from a tool inside a lich session inherits that
    // session's variables, so it would also take the parent's commands.
    if (e.isInteractive && state.link === undefined) {
      state.link = await linkFromEnv($)
      state.lang = promptLang(await $.env.get("LICH_PROMPT_LANG"))
      const link = state.link
      if (link) $.clock.after(0, () => void poll($, state, link))
    }
    return next(e)
  })

  on("turn.start", ($, e, next) => {
    state.turnId = e.turnId
    return next(e)
  })

  on("turn.complete", ($, e, next) => {
    if (e.turnId === state.turnId) state.turnId = undefined
    return next(e)
  })

  on("turn.step", async function* ($, e, next) {
    return yield* next({
      ...e,
      ...(state.model !== undefined && { model: state.model }),
      ...(state.effort !== undefined && { effort: state.effort }),
    })
  })
}

files.hooks/mod-status.js:
// Shows the relay errands a Claude Code session is part of in its status line:
// who it owes an answer, the tasks it handed out that are still running, and
// the answers waiting to be collected. Contract: ../docs/mod-status.md,
// canonical in https://github.com/omartelo/lich/blob/main/docs/hooks/mod-status.md
//
// The one contract that reads rather than reports, and reading never collects:
// an answer listed as ready stays in the inbox for the agent.
//
// Every function that takes `$` is declared here at the top level: the loader
// refuses a module that hands `$` to a nested function.

import { setStatusPart } from "./status-line.js"

// Sent as X-Lich-Plugin on every request; bumped at release (CLAUDE.md, Release).
const PLUGIN_VERSION = "0.20.0"

// The contract asks for a read at most every few seconds; the worker count in
// agent-cards.js polls lich on the same period.
const READ_EVERY_MS = 5000

/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {{ ticket: string, from: string, asked: string }} Owed
 * @typedef {{ ticket: string, target: string, state: string }} Open
 * @typedef {{ ticket: string, target: string, status: string }} Ready
 * @typedef {{ owed: Owed[], open: Open[], ready: Ready[] }} Status
 * @typedef {{ url: string, timer?: import('claude-code').Timer, reading: boolean }} State
 */

/** @param {number} count @param {string} noun */
function counted(count, noun) {
  return `${count} ${noun}${count === 1 ? "" : "s"}`
}

/**
 * The status line's text for `status`, or undefined when there is nothing to
 * show. A task out on a session waiting for a human is called out: nobody but
 * the user can move it.
 *
 * @param {Status} status
 */
function errandsLine({ owed, open, ready }) {
  const pieces = []
  if (owed.length === 1 && owed[0].from) pieces.push(`owes "${owed[0].from}" an answer`)
  else if (owed.length > 0) pieces.push(`owes ${counted(owed.length, "answer")}`)
  if (open.length > 0) {
    const waiting = open.filter((errand) => errand.state === "waiting").length
    pieces.push(`${counted(open.length, "task")} out${waiting > 0 ? ` (${waiting} waiting)` : ""}`)
  }
  if (ready.length > 0) pieces.push(`${counted(ready.length, "answer")} to collect`)
  return pieces.length === 0 ? undefined : pieces.join(", ")
}

/**
 * @param {Engine} $
 * @returns {Promise<string | undefined>}
 */
async function statusUrlFromEnv($) {
  const [port, token, session] = await Promise.all([
    $.env.get("LICH_PORT"),
    $.env.get("LICH_TOKEN"),
    $.env.get("LICH_SESSION_ID"),
  ])
  if (!port || !token || !session) return undefined
  return `http://127.0.0.1:${port}/mod/status?token=${encodeURIComponent(token)}&session_id=${encodeURIComponent(session)}`
}

/**
 * One read. A failed one draws nothing from lich until a read works again,
 * and is never retried; a 404 is a lich older than the contract, which stops
 * the reads for the session.
 *
 * @param {Engine} $
 * @param {State} state
 */
async function read($, state) {
  if (state.reading) return
  state.reading = true
  /** @type {string | undefined} */
  let line
  try {
    const response = await $.http.fetch(state.url, { headers: { "X-Lich-Plugin": PLUGIN_VERSION } })
    if (response.status === 404) state.timer?.cancel()
    if (response.ok) line = errandsLine(JSON.parse(response.text))
  } catch {
    // Unreachable or unreadable: the line goes until the next read works.
  }
  state.reading = false
  setStatusPart("errands", line)
  $.ui.invalidate("ui.render")
}

/** @param {import('claude-code').On} on */
export function register(on) {
  // Interactive sessions only: a `claude -p` started from a tool inside a lich
  // session inherits its variables, and would read the parent's errands.
  on("session.start", { isInteractive: true }, async ($, e, next) => {
    const url = await statusUrlFromEnv($)
    if (url) {
      /** @type {State} */
      const state = { url, reading: false }
      state.timer = $.clock.every(READ_EVERY_MS, () => read($, state))
      read($, state)
    }
    return next(e)
  })
}

files.hooks/mod-usage.js:
// Reports what a Claude Code session measured about itself to lich. Contract:
// ../docs/mod-usage.md, canonical in
// https://github.com/omartelo/lich/blob/main/docs/hooks/mod-usage.md
//
// A Claude Code mod, not a hook script: hooks/hooks.json names this file under
// `modules`, beside mod-control.js. It hooks `session.measure`, which fires at
// start, at the end of every main-thread turn and when a rate-limit window
// moves, and posts the context window, the rate limits and the cost to lich,
// which shows those instead of the figures it derives.
//
// Every function that takes `$` is declared here at the top level: the loader
// refuses a module that hands `$` to a nested function.

// Sent as X-Lich-Plugin on every request; bumped at release (CLAUDE.md, Release).
const PLUGIN_VERSION = "0.20.0"

/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {import('claude-code').SessionMeasureInput} Measure
 * @typedef {{ base: string, token: string, session: string }} Link
 * @typedef {{
 *   started: Promise<Link | undefined>,
 *   sending: Promise<void>,
 *   gone: boolean,
 * }} State
 */

/**
 * @param {Engine} $
 * @returns {Promise<Link | undefined>}
 */
async function linkFromEnv($) {
  const [port, token, session] = await Promise.all([
    $.env.get("LICH_PORT"),
    $.env.get("LICH_TOKEN"),
    $.env.get("LICH_SESSION_ID"),
  ])
  if (!port || !token || !session) return undefined
  return { base: `http://127.0.0.1:${port}`, token, session }
}

/**
 * The body lich takes: Claude Code's figures under the contract's names, an
 * absent figure left out rather than zeroed.
 *
 * @param {string} session
 * @param {string} conversation
 * @param {Measure} e
 */
function usageBody(session, conversation, e) {
  return {
    session_id: session,
    conversation_id: conversation,
    context: {
      window: e.context.window,
      ...(e.context.tokens !== undefined && { tokens: e.context.tokens }),
      ...(e.context.percent !== undefined && { percent: e.context.percent }),
    },
    rate_limits: e.rateLimits.map((limit) => ({
      kind: limit.kind,
      percent_used: limit.percentUsed,
      ...(limit.resetsAt !== undefined && { resets_at: limit.resetsAt }),
    })),
    ...(e.cost !== undefined && { cost_usd: e.cost.usd }),
  }
}

/**
 * Posts one measurement, once the session's link is known. A report that
 * fails is dropped: the next measurement carries the whole figures again.
 *
 * @param {Engine} $
 * @param {State} state
 * @param {Measure} e
 */
async function report($, state, e) {
  const link = await state.started
  if (!link || state.gone) return
  try {
    const response = await $.http.fetch(`${link.base}/mod/usage?token=${link.token}`, {
      method: "POST",
      headers: { "content-type": "application/json", "X-Lich-Plugin": PLUGIN_VERSION },
      body: JSON.stringify(usageBody(link.session, await $.session.id(), e)),
    })
    // A lich older than the contract: nothing it would take is coming.
    if (response.status === 404) state.gone = true
  } catch {
    // The contract drops a report that cannot be sent; it never retries one.
  }
}

/** @param {import('claude-code').On} on */
export function register(on) {
  /** @type {(link: Link | undefined) => void} */
  let start = () => {}
  /** @type {State} */
  const state = {
    started: new Promise((resolve) => {
      start = resolve
    }),
    sending: Promise.resolve(),
    gone: false,
  }

  // Interactive sessions only: a `claude -p` started from a tool inside a lich
  // session inherits that session's variables, and its figures would land on
  // the parent's card. Its measurements wait on a link that never comes.
  on("session.start", { isInteractive: true }, async ($, e, next) => {
    start(await linkFromEnv($))
    return next(e)
  })

  on("session.measure", ($, e, next) => {
    // One at a time, in order: lich keeps the latest report, so an older one
    // landing last would put stale figures back on the card.
    state.sending = state.sending.then(() => report($, state, e))
    return next(e)
  })
}

files.hooks/self-command.js:
// Lets a Claude Code session run one of its own built-in slash commands when the
// person asks for one ("run /compact"). Plugin side only: lich's `control`
// refuses a session controlling itself, so nothing here goes through lich.
// Described in ../docs/self-command.md.
//
// The model asks through a tool it already reaches for, and the mod answers
// that tool's refusal by queueing the command: the Skill tool, which refuses a
// built-in ("compact is a built-in CLI command, not a skill"), and lich's
// control_session, which refuses the session's own ("... is this session, and
// a session cannot control itself"), told apart by `lich whoami`. A tool of the mod's own is not an option:
// Claude Code lists it as `mcp__lich__<name>`, and `$.tool.register` refuses
// that in a session whose MCP config already has lich's own server under that
// name, which is every lich session (measured on 2.1.295).
//
// Every function that takes `$` is declared here at the top level: the loader
// refuses a module that hands `$` to a nested function.

import { promptLang, say } from "./prompt-text.js"

// Run through a mod, these save what they set as the default for every new
// session (measured on Claude Code 2.1.288 and 2.1.289).
const SAVES_A_DEFAULT = new Set(["model", "effort"])

// The name Claude Code gives lich's tool (measured on 2.1.295 with lich's MCP
// server).
const CONTROL_TOOL = "mcp__lich__control_session"

const WHOAMI_TIMEOUT_MS = 2_000

// `list_sessions` leaves this session out, so the model does not know its own
// label; the note names it by `LICH_SESSION_ID`, which lich takes as a target too.
/**
 * @typedef {import('claude-code').EngineInterface} Engine
 * @typedef {{ sessionId: string | undefined }} State
 */

/**
 * Queues `/name args` for when the session is idle. `$.command.run` rejects
 * inside a hook the turn is waiting on, so it is called from a timer; a
 * command that then fails has no turn left to answer, so its error goes to a
 * toast.
 *
 * @param {Engine} $
 * @param {string} name
 * @param {string} args
 */
async function runCommand($, name, args) {
  try {
    await $.command.run({ command: name, args })
  } catch (error) {
    $.ui.toast(`/${name} did not run: ${error instanceof Error ? error.message : String(error)}`)
  }
}

/**
 * @param {Engine} $
 * @param {string} name
 */
async function isBuiltin($, name) {
  const commands = await $.command.list()
  return commands.some((command) => command.name === name && command.source === "builtin")
}

/**
 * Queues the built-in `name` the model asked for, or refuses it. Undefined
 * when `name` is no built-in, so the caller answers with the tool's own reply.
 *
 * @param {Engine} $
 * @param {string} name
 * @param {string} args
 */
async function queueBuiltin($, name, args) {
  if (SAVES_A_DEFAULT.has(name)) {
    return {
      deny:
        say(promptLang(await $.env.get("LICH_PROMPT_LANG")), "denyDefaultSaved", { name }),
    }
  }
  if (!(await isBuiltin($, name))) return undefined
  $.clock.after(0, () => runCommand($, name, args))
  return `/${[name, args].filter(Boolean).join(" ")}`
}

/**
 * Whether `target` names this session: its id, or the label or name
 * `lich whoami` prints for it, which lich matches without regard to case.
 *
 * @param {Engine} $
 * @param {string} target
 * @param {string} sessionId
 */
async function isThisSession($, target, sessionId) {
  if (target === sessionId) return true
  const lich = await $.env.get("LICH_BIN")
  if (!lich) return false
  const { exitCode, stdout } = await $.process.run([lich, "whoami", "--json"], { timeoutMs: WHOAMI_TIMEOUT_MS })
  if (exitCode !== 0) return false
  const self = JSON.parse(stdout)
  const wanted = target.toLowerCase()
  return [self.label, self.name].some((name) => typeof name === "string" && name.toLowerCase() === wanted)
}

/** @param {string} name */
const bareName = (name) => name.trim().replace(/^\//, "")

/** @param {import('claude-code').On} on */
export function register(on) {
  /** @type {State} */
  const state = { sessionId: undefined }

  // Interactive lich sessions only: outside lich the plugin adds nothing, and a
  // `claude -p` started from a tool inside a lich session inherits its variables.
  on("session.start", { isInteractive: true }, async ($, e, next) => {
    state.sessionId = await $.env.get("LICH_SESSION_ID")
    if (state.sessionId) $.ui.invalidate("tool.describe")
    return next(e)
  })

  on("tool.describe", { tool: "Skill" }, async ($, e, next) => {
    const described = await next(e)
    if (!state.sessionId) return described
    return { ...described, description: described.description + say(promptLang(await $.env.get("LICH_PROMPT_LANG")), "skillNote") }
  })

  // The Skill tool runs first: a skill, or a built-in it serves as a prompt
  // (/init, /review), stays its own. Only what it refused is taken.
  on("tool.call", { tool: "Skill" }, async ($, e, next) => {
    const native = await next(e)
    if (!state.sessionId || !("isError" in native && native.isError)) return native
    const name = bareName(e.skill)
    const queued = await queueBuiltin($, name, e.args?.trim() ?? "")
    if (queued === undefined) return native
    if (typeof queued !== "string") return queued
    return {
      result: { success: true, commandName: name },
      context: [say(promptLang(await $.env.get("LICH_PROMPT_LANG")), "skillQueued", { queued })],
    }
  })

  on("tool.describe", { tool: CONTROL_TOOL }, async ($, e, next) => {
    const described = await next(e)
    if (!state.sessionId) return described
    return { ...described, description: described.description + say(promptLang(await $.env.get("LICH_PROMPT_LANG")), "controlNote", { sessionId: state.sessionId }) }
  })

  // lich answers first: a command for another session is its own. Only its
  // refusal of this session as the target is taken.
  on("tool.call", { tool: CONTROL_TOOL }, async ($, e, next) => {
    const native = await next(e)
    if (!state.sessionId || e.action !== "command" || typeof e.value !== "string") return native
    if (!("isError" in native && native.isError)) return native
    if (!(await isThisSession($, e.session, state.sessionId))) return native
    const queued = await queueBuiltin($, bareName(e.value), e.args?.trim() ?? "")
    if (queued === undefined) return native
    if (typeof queued !== "string") return queued
    return { result: say(promptLang(await $.env.get("LICH_PROMPT_LANG")), "controlQueued", { queued }) }
  })
}

